INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('BCX-350', 'bot-chuoi-xanh-350g', 'Bột chuối xanh', 'Kháng tinh bột · Hũ 350g', 'chuoi', 'main', 139000, NULL, 97000, 38000, 500, '/assets/img/bcx-350.webp', '/assets/img/bcx-350-bg.webp', 'Chuối xanh Tây Nguyên sấy nhiệt thấp, nghiền mịn để giữ tinh bột kháng. Pha sinh tố, nấu cháo, làm bánh, không đường thêm.', 'Ở vườn Đắk Lắk, chuối được thu khi còn xanh già, lúc tinh bột kháng cao nhất. Nhà máy sấy ở nhiệt độ thấp rồi nghiền mịn, không thêm đường, không phụ gia. Mỗi hũ có mã QR lô hàng: bạn thấy vườn trồng, ngày chế biến và phiếu kiểm nghiệm hàm lượng tinh bột kháng.', '["Giàu tinh bột kháng và chất xơ, hỗ trợ tiêu hoá", "No lâu, dễ thay một phần tinh bột trong bữa ăn", "100% chuối xanh, không đường, không phụ gia", "Công bố hàm lượng tinh bột kháng theo phiếu kiểm nghiệm từng lô"]', '1–2 thìa (khoảng 15g) pha với 200ml nước ấm hoặc sữa, hoặc xay cùng sinh tố. Có thể thay một phần bột mì khi làm bánh, khuấy vào cháo, yến mạch. Đậy kín, bảo quản nơi khô mát.', '100% chuối xanh Tây Nguyên.', '350g', '["Chủ lực số 1", "Kiểm nghiệm tinh bột kháng"]', '["duong-huyet", "van-phong"]', NULL, 'Bột chuối xanh kháng tinh bột 350g, không đường | DaLa', 'Bột chuối xanh Tây Nguyên sấy nhiệt thấp giữ tinh bột kháng, 100% chuối, không đường. Quét QR thấy vườn và phiếu kiểm nghiệm. Giao toàn quốc.', 450, 12, 12, 14, 0, 1);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('BCX-S10', 'bot-chuoi-xanh-10-goi', 'Bột chuối xanh dạng gói', 'Dùng thử · Hộp 10 gói × 15g', 'chuoi', 'trial', 69000, NULL, 48000, 22000, 600, '/assets/img/bcx-s10.webp', '/assets/img/bcx-s10-bg.webp', 'Mỗi gói 15g vừa một ly, mang đi làm, đi tập tiện lợi. Cỡ dùng thử cho lần đầu làm quen bột chuối xanh.', 'Gói nhỏ cho người bận rộn: xé gói, đổ vào bình lắc với nước hoặc sữa là xong bữa phụ. Cùng nguyên liệu và quy trình với hũ 350g.', '["10 gói 15g, pha 1 phút", "Tiện mang theo văn phòng, phòng tập", "Cỡ dùng thử trước khi mua hũ lớn"]', 'Pha 1 gói với 150–200ml nước ấm, sữa hạt hoặc xay sinh tố.', '100% chuối xanh Tây Nguyên.', '10 × 15g', '["Dùng thử"]', '["van-phong", "duong-huyet"]', NULL, 'Bột chuối xanh gói 15g tiện lợi, hộp 10 gói | DaLa', 'Bột chuối xanh dạng gói 15g pha 1 phút, không đường. Cỡ dùng thử cho người bận rộn.', 220, 16, 8, 12, 0, 5);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('CLTH-100', 'chanh-leo-say-thang-hoa-100g', 'Chanh leo sấy thăng hoa', '100% nguyên chất · Túi zip 100g', 'chanhleo', 'main', 129000, NULL, 90000, 62000, 400, '/assets/img/clth-100.webp', '/assets/img/clth-100-bg.webp', 'Lát chanh leo nguyên ruột sấy thăng hoa: giòn tan, chua thơm tự nhiên, không đường, không chiên dầu.', 'Tây Nguyên trồng 86,4% diện tích chanh leo cả nước. DaLa chọn trái tím chín cây, cắt lát rồi sấy thăng hoa ở nhiệt độ âm để giữ màu, mùi và vị chua thơm. Không đường, không chất bảo quản, chỉ có chanh leo.', '["Giòn tan, ăn vặt nhẹ nhàng giữa giờ", "Pha nước, rắc sữa chua, granola, trang trí bánh", "Không đường thêm, không chiên dầu", "Túi zip giữ giòn, mang theo tiện"]', 'Ăn trực tiếp; thả 3–4 lát vào nước ấm hoặc trà; rắc lên sữa chua, smoothie bowl. Đóng kín túi zip sau khi mở để giữ giòn.', '100% chanh leo tím Tây Nguyên.', '100g', '["Chủ lực", "Biểu tượng Tây Nguyên"]', '["me-be", "van-phong", "qua-tang"]', NULL, 'Chanh leo sấy thăng hoa 100% nguyên chất 100g | DaLa', 'Chanh leo Tây Nguyên sấy thăng hoa giòn tan, không đường, không chiên dầu. Quét QR thấy vườn trồng. Giao toàn quốc.', 180, 22, 16, 6, 1, 2);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('CLTH-25', 'chanh-leo-say-thang-hoa-25g', 'Chanh leo sấy thăng hoa', 'Dùng thử · Gói 25g', 'chanhleo', 'trial', 39000, NULL, 27000, 18000, 800, '/assets/img/clth-25.webp', '/assets/img/clth-25-bg.webp', 'Gói nhỏ 25g để thử vị giòn chua của chanh leo sấy thăng hoa, vừa một lần ăn.', 'Cỡ dùng thử cho người mua lần đầu, cho vào túi xách, hộp cơm hay làm quà nhỏ.', '["Vừa một lần ăn", "Giá dễ thử", "100% chanh leo"]', 'Ăn trực tiếp hoặc pha nước.', '100% chanh leo tím Tây Nguyên.', '25g', '["Dùng thử"]', '["van-phong", "me-be"]', NULL, 'Chanh leo sấy thăng hoa gói 25g dùng thử | DaLa', 'Gói dùng thử chanh leo sấy thăng hoa 25g, giòn tan, không đường.', 50, 14, 10, 3, 0, 6);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COT-1L', 'cot-chanh-leo-1l', 'Cốt chanh leo nguyên chất', 'Chai 1L cho quán trà, cà phê', 'chanhleo', 'b2b', 139000, NULL, 115000, 59000, 300, '/assets/img/cot-1l.webp', '/assets/img/cot-1l-bg.webp', 'Cốt chanh leo 100% nguyên chất, không đường, vị ổn định quanh năm cho quán trà, cà phê. Pha 1 cốt : 4 nước.', 'Quán trà cần một vị chanh leo đều tay mỗi ly. Cốt DaLa ép từ chanh leo tím Tây Nguyên, không pha đường để quán tự cân vị. Giao gần ở Tây Nguyên và Nam Trung Bộ, có giá sỉ theo thùng.', '["100% chanh leo, không đường, quán tự cân vị", "Vị ổn định từng lô, có QR truy xuất", "Giá sỉ cho quán, xuất hoá đơn", "Giao nhanh Tây Nguyên, Nam Trung Bộ"]', 'Tỷ lệ gợi ý 1 cốt : 4 nước. Lắc đều trước khi dùng. Sau khi mở, bảo quản lạnh và dùng theo hạn ghi trên nhãn.', '100% ruột chanh leo tím Tây Nguyên.', '1 lít', '["Chủ lực · B2B", "Không đường"]', '["quan-tra"]', NULL, 'Cốt chanh leo nguyên chất 1L không đường cho quán | DaLa', 'Cốt chanh leo 100% nguyên chất, không đường, vị ổn định cho quán trà, cà phê. Giá sỉ, giao nhanh Tây Nguyên.', 1150, 9, 9, 28, 1, 3);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COT-250', 'cot-chanh-leo-250ml', 'Cốt chanh leo nguyên chất', 'Chai 250ml dùng tại nhà', 'chanhleo', 'retail', 45000, NULL, 32000, 18000, 500, '/assets/img/cot-250.webp', '/assets/img/cot-250-bg.webp', 'Chai nhỏ 250ml không đường để pha nước chanh leo, trà chanh leo, làm sốt tại nhà.', 'Cùng cốt nguyên chất của quán, đóng chai nhỏ cho gia đình. Một chai pha được khoảng 5 ly.', '["Pha khoảng 5 ly", "Không đường, tự cân vị", "Làm sốt, làm bánh, pha trà"]', 'Pha 1 cốt : 4 nước, thêm đá, mật ong tuỳ khẩu vị.', '100% ruột chanh leo tím Tây Nguyên.', '250ml', '["Không đường"]', '["duong-huyet", "van-phong"]', NULL, 'Cốt chanh leo 250ml nguyên chất không đường | DaLa', 'Cốt chanh leo nguyên chất 250ml, không đường, pha nước, trà, làm sốt tại nhà.', 320, 6, 6, 16, 1, 7);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('KL-250', 'khoai-lang-say-deo-250g', 'Khoai lang sấy dẻo', 'Không đường · Túi 250g', 'khoailang', 'addon', 59000, NULL, 41000, 20000, 500, '/assets/img/kl-250.webp', '/assets/img/kl-250-bg.webp', 'Khoai lang mật sấy dẻo tự nhiên, ngọt từ củ, không thêm đường. Chỉ bán kèm đơn hàng hoặc trong combo.', 'Khoai lang được hấp chín rồi sấy dẻo chậm, giữ vị ngọt tự nhiên của củ. Món ăn vặt quen thuộc, dẻo thơm, ăn kèm buổi xế.', '["Ngọt tự nhiên, không đường thêm", "Dẻo thơm, ăn no lâu", "Mua kèm đơn hàng với giá tốt"]', 'Ăn trực tiếp, hâm nóng 10 giây cho mềm thơm.', '100% khoai lang.', '250g', '["Chỉ bán kèm"]', '["van-phong", "me-be"]', NULL, 'Khoai lang sấy dẻo không đường 250g | DaLa', 'Khoai lang sấy dẻo tự nhiên, không thêm đường, mua kèm đơn hàng DaLa.', 290, 20, 14, 5, 0, 8);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('QUA-TET', 'hop-qua-tet-nang-cao-nguyen', 'Hộp quà Nắng Cao Nguyên', 'Quà Tết 2027 · 4 sản phẩm + trái tươi', 'qua', 'gift', 399000, NULL, 299000, 180000, 200, '/assets/img/qua-tet.webp', '/assets/img/qua-tet.webp', 'Hộp quà sơn mài xanh với chanh leo sấy, bột chuối xanh, khoai lang dẻo, cốt chanh leo và trái chanh leo tươi, kèm thư tay của nông dân.', 'Mỗi hộp là một câu chuyện vùng: từ vườn Đắk Lắk qua nhà máy đến tay người nhận. Có QR xem vườn trồng, có thư của người trồng, xuất hoá đơn cho doanh nghiệp và in logo theo yêu cầu khi đặt số lượng.', '["Quà có câu chuyện vùng, không đụng hàng", "Thư tay nông dân và QR xem vườn", "Xuất hoá đơn, in thiệp doanh nghiệp", "Giá sỉ từ 20 hộp"]', 'Bảo quản nơi khô mát; trái tươi dùng trong 7 ngày.', 'Chanh leo sấy thăng hoa, bột chuối xanh, khoai lang sấy dẻo, cốt chanh leo, chanh leo tươi theo mùa.', 'Hộp 35×25cm', '["Quà Tết 2027", "Xuất hoá đơn"]', '["qua-tang"]', NULL, 'Hộp quà Tết Nắng Cao Nguyên 2027, đặc sản Đắk Lắk | DaLa', 'Hộp quà Tết đặc sản Tây Nguyên: chanh leo sấy, bột chuối xanh, khoai lang dẻo, cốt chanh leo. Có QR, thư tay nông dân, xuất hoá đơn.', 1800, 35, 25, 10, 1, 4);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('CL-2KG', 'chanh-leo-tim-tuoi-2kg', 'Chanh leo tím tươi', 'Hộp 2kg có QR · Hái sáng, giao trong 48 giờ', 'tuoi', 'seasonal', 119000, NULL, NULL, 95000, 150, '/assets/img/cl-2kg.webp', '/assets/img/cl-2kg-bg.webp', 'Chanh leo tím loại 1 hái sáng tại vườn, đóng hộp 2kg có QR, giao trong 48 giờ.', 'Trái chín cây, vỏ tím căng, ruột vàng thơm. Hộp có QR ghi tên vườn và ngày hái. Hàng theo mùa, số lượng có hạn.', '["Hái sáng, giao trong 48 giờ", "Loại 1, có QR vườn trồng", "Hợp làm quà, pha nước tại nhà"]', 'Bảo quản nơi thoáng mát, trái hơi nhăn vỏ là ngọt nhất.', 'Chanh leo tím tươi.', '2kg', '["Theo mùa"]', '["qua-tang", "me-be"]', NULL, 'Chanh leo tím tươi hộp 2kg hái tại vườn Đắk Lắk | DaLa', 'Chanh leo tím tươi loại 1 hái sáng, hộp 2kg có QR vườn trồng, giao trong 48 giờ.', 2200, 30, 20, 12, 1, 9);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-KHOE', 'combo-khoe-moi-ngay', 'Combo khỏe mỗi ngày', 'Bột chuối + chanh leo sấy + khoai lang', 'combo', 'combo', 289000, 327000, NULL, 120000, 0, '/assets/img/combo-khoe.webp', '/assets/img/combo-khoe-bg.webp', 'Ba món cho một ngày nhẹ bụng: bột chuối xanh buổi sáng, chanh leo sấy giữa giờ, khoai lang dẻo buổi xế. Tiết kiệm 12% so với mua lẻ.', 'Combo được xếp theo nhịp một ngày làm việc: sáng pha bột chuối, trưa nhâm nhi chanh leo, chiều một túi khoai dẻo. Đủ dùng khoảng 3 tuần cho một người.', '["Tiết kiệm 38.000đ so với mua lẻ", "Đủ dùng khoảng 3 tuần", "Hợp tặng người thân lo ăn uống lành mạnh"]', 'Xem hướng dẫn trên từng sản phẩm.', 'Bột chuối xanh 350g, chanh leo sấy thăng hoa 100g, khoai lang sấy dẻo 250g.', '3 sản phẩm', '["Online −12%", "Bán chạy"]', '["van-phong", "duong-huyet", "qua-tang"]', '[{"sku": "BCX-350", "qty": 1}, {"sku": "CLTH-100", "qty": 1}, {"sku": "KL-250", "qty": 1}]', 'Combo khỏe mỗi ngày: bột chuối, chanh leo sấy, khoai lang | DaLa', 'Combo 3 sản phẩm lành mạnh từ Tây Nguyên, tiết kiệm 12%. Không đường thêm, có QR truy xuất.', 950, 25, 20, 15, 1, 10);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-THU', 'bo-dung-thu-3-vi', 'Bộ dùng thử 3 vị', 'Bột chuối gói + chanh leo 25g + cốt 250ml', 'combo', 'combo', 129000, 153000, NULL, 58000, 0, '/assets/img/combo-dung-thu.webp', '/assets/img/combo-dung-thu.webp', 'Lần đầu biết DaLa? Thử đủ 3 dòng sản phẩm chủ lực với giá nhỏ, rồi chọn món hợp mình.', 'Bộ dùng thử gom cỡ nhỏ của cả ba dòng: bột chuối xanh, chanh leo sấy thăng hoa và cốt chanh leo. Cách rẻ nhất để biết vị DaLa.', '["Thử cả 3 dòng chủ lực", "Tiết kiệm 24.000đ", "Hợp làm quà nhỏ"]', 'Xem hướng dẫn trên từng sản phẩm.', 'Bột chuối xanh 10 gói × 15g, chanh leo sấy thăng hoa 25g, cốt chanh leo 250ml.', '3 sản phẩm', '["Mới", "Cho người mua lần đầu"]', '["van-phong", "duong-huyet", "me-be"]', '[{"sku": "BCX-S10", "qty": 1}, {"sku": "CLTH-25", "qty": 1}, {"sku": "COT-250", "qty": 1}]', 'Bộ dùng thử 3 vị DaLa: bột chuối, chanh leo sấy, cốt chanh leo', 'Thử cả 3 dòng sản phẩm DaLa với giá 129.000đ: bột chuối xanh, chanh leo sấy thăng hoa, cốt chanh leo.', 600, 18, 14, 12, 1, 11);
INSERT INTO products (sku, slug, name, subtitle, line, kind, price, compare_price, wholesale_price, cost, stock, image, image_bg, short_desc, story, benefits, usage, ingredients, weight, badges, personas, combo_items, seo_title, seo_desc, weight_g, length_cm, width_cm, height_cm, fragile, sort) VALUES ('COMBO-NHA', 'combo-an-vat-ca-nha', 'Combo ăn vặt cả nhà', 'Chanh leo sấy 100g + 2 gói 25g + khoai lang', 'combo', 'combo', 229000, 266000, NULL, 118000, 0, '/assets/img/combo-ca-nha.webp', '/assets/img/combo-ca-nha.webp', 'Đồ ăn vặt từ trái cây thật cho cả nhà: không đường thêm, không chiên dầu, rõ vườn trồng.', 'Thay bánh kẹo bằng trái cây sấy: một túi chanh leo lớn để chia, hai gói nhỏ cho vào cặp, một túi khoai dẻo cho buổi chiều.', '["Không đường thêm, không chiên dầu", "Tiết kiệm 37.000đ", "Gói nhỏ chia phần tiện"]', 'Xem hướng dẫn trên từng sản phẩm.', 'Chanh leo sấy thăng hoa 100g, 2 gói chanh leo 25g, khoai lang sấy dẻo 250g.', '4 sản phẩm', '["Gia đình"]', '["me-be", "van-phong"]', '[{"sku": "CLTH-100", "qty": 1}, {"sku": "CLTH-25", "qty": 2}, {"sku": "KL-250", "qty": 1}]', 'Combo ăn vặt trái cây sấy cho cả nhà | DaLa', 'Combo ăn vặt trái cây sấy không đường cho gia đình: chanh leo sấy thăng hoa và khoai lang dẻo.', 600, 25, 18, 12, 1, 12);
