INSERT INTO posts (slug, title, excerpt, body, cover, seo_desc) VALUES ('tinh-bot-khang-la-gi', 'Tinh bột kháng là gì và vì sao chuối xanh được nhắc nhiều?', 'Tinh bột kháng là loại tinh bột đi qua ruột non mà không bị tiêu hoá hết. Chuối xanh là một trong những nguồn tự nhiên phổ biến.', 'Tinh bột kháng (resistant starch) là phần tinh bột không bị enzyme tiêu hoá hết ở ruột non, đi xuống ruột già và trở thành "thức ăn" cho vi khuẩn có lợi, giống như chất xơ.
INSERT INTO posts (slug, title, excerpt, body, cover, seo_desc) VALUES ('say-thang-hoa-khac-say-thuong', 'Sấy thăng hoa khác sấy thường thế nào?', 'Sấy thăng hoa làm đông trái cây rồi rút nước trong chân không, giữ màu, mùi và độ giòn mà không cần chiên dầu.', 'Sấy thường dùng nhiệt để làm bay hơi nước, dễ làm trái cây sẫm màu và mất mùi. Sấy thăng hoa (freeze-drying) làm đông trái cây ở nhiệt độ âm sâu, sau đó hạ áp suất để nước đá thăng hoa thành hơi.
INSERT INTO posts (slug, title, excerpt, body, cover, seo_desc) VALUES ('cong-thuc-tra-chanh-leo-cot-nguyen-chat', '3 công thức trà chanh leo với cốt nguyên chất', 'Tỷ lệ 1 cốt : 4 nước cho ly chanh leo đậm vị, cùng 3 biến tấu dễ làm tại nhà hay ở quán.', 'Chanh leo đá: 40ml cốt DaLa, 160ml nước lạnh, 15ml mật ong hoặc syrup, đá viên.
